    1	// Package ini parses a simple INI dialect:
    2	//
    3	//   - Lines are trimmed of surrounding whitespace. Empty lines are ignored.
    4	//   - Lines starting with ';' or '#' are comments.
    5	//   - "[name]" starts a section. Section names are trimmed and lower-cased.
    6	//     Keys before any section belong to the section "" (empty string).
    7	//   - "key = value" sets a key. Keys are trimmed and lower-cased; values are
    8	//     trimmed. The first '=' separates key and value, so values may contain '='.
    9	//   - A value wrapped in double quotes has the quotes removed and keeps its
   10	//     inner whitespace exactly ("  a  " -> "  a  ").
   11	//   - An inline comment starts at " ;" or " #" (whitespace then ; or #) in an
   12	//     unquoted value and runs to the end of the line.
   13	//   - A repeated key in the same section overwrites the earlier value.
   14	//   - Any other line is a syntax error reported as *SyntaxError with the
   15	//     1-based line number.
   16	package ini
   17	
   18	import (
   19		"bufio"
   20		"fmt"
   21		"io"
   22		"strings"
   23	)
   24	
   25	// File maps section -> key -> value.
   26	type File map[string]map[string]string
   27	
   28	// SyntaxError reports a malformed line.
   29	type SyntaxError struct {
   30		Line int
   31		Text string
   32	}
   33	
   34	func (e *SyntaxError) Error() string { return fmt.Sprintf("ini: line %d: syntax error: %q", e.Line, e.Text) }
   35	
   36	// Get returns the value of key in section.
   37	func (f File) Get(section, key string) (string, bool) {
   38		s, ok := f[strings.ToLower(section)]
   39		if !ok {
   40			return "", false
   41		}
   42		v, ok := s[strings.ToLower(key)]
   43		return v, ok
   44	}
   45	
   46	// Parse reads an INI document.
   47	func Parse(r io.Reader) (File, error) {
   48		f := File{}
   49		section := ""
   50		sc := bufio.NewScanner(r)
   51		n := 0
   52		for sc.Scan() {
   53			n++
   54			line := sc.Text()
   55			if line == "" || line[0] == ';' {
   56				continue
   57			}
   58			if line[0] == '[' && line[len(line)-1] == ']' {
   59				section = strings.TrimSpace(line[1 : len(line)-1])
   60				continue
   61			}
   62			i := strings.LastIndex(line, "=")
   63			if i < 0 {
   64				return nil, &SyntaxError{Line: n, Text: line}
   65			}
   66			key := strings.ToLower(strings.TrimSpace(line[:i]))
   67			val := strings.TrimSpace(line[i+1:])
   68			if j := strings.Index(val, ";"); j >= 0 {
   69				val = strings.TrimSpace(val[:j])
   70			}
   71			if len(val) >= 2 && val[0] == '"' && val[len(val)-1] == '"' {
   72				val = strings.TrimSpace(val[1 : len(val)-1])
   73			}
   74			if f[section] == nil {
   75				f[section] = map[string]string{}
   76			}
   77			if _, exists := f[section][key]; !exists {
   78				f[section][key] = val
   79			}
   80		}
   81		return f, sc.Err()
   82	}

